    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out."""
    # Simple approach: find first differing position and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # Strings are identical up to min length
        if len(s_in) == len(s_out):
            return "", "", -1
        elif len(s_in) > len(s_out):
            # Remove characters from end
            old_sub = s_in[len(s_out):]
            new_sub = ""
            pos = len(s_out)
        else:
            # Add characters to end  
            old_sub = ""
            new_sub = s_out[len(s_in):]
            pos = len(s_in)
    else:
        # Find what to replace
        old_sub = s_in[pos:pos+1]  # Just one character for now
        new_sub = s_out[pos:pos+1]  # Just one character for now

    return old_sub, new_sub, pos

def propose_rule_candidates(s_in, s_out):
    """Propose possible rule candidates from a change."""
    # For simplicity, let's start with exact character substitutions
    candidates = []

    # Try single character replacements
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            candidates.append((s_in[i], s_out[i]))

    # Also consider substring replacements if applicable
    if len(s_in) > 1 and len(s_out) > 1:
        # Try replacing the entire string with another
        if s_in != s_out:
            candidates.append((s_in, s_out))

    return candidates

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules perform on the corpus."""
    predictions = apply_rules(inputs, rules)
    correct = sum(1 for pred, out in zip(predictions, outputs) if pred == out)
    return correct / len(inputs)

def find_over_applications(inputs, outputs, rules):
    """Find inputs that are incorrectly modified by rules."""
    predictions = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, pred, out) in enumerate(zip(inputs, predictions, outputs)):
        if pred != out and inp != out:  # The prediction is wrong but input was not supposed to change
            over_apps.append((i, inp, pred))
    return over_apps

def simulate_rule_chain(s, rules):
    """Simulate applying rules to a single string step by step."""
    trace = []
    current = s
    for pattern, replacement in rules:
        prev = current
        current = current.replace(pattern, replacement)
        trace.append({
            'pattern': pattern,
            'replacement': replacement,
            'before': prev,
            'after': current
        })
    return trace

def build_proxy_rules(pattern, replacement, proxy="__X__"):
    """Build pre/post rules to protect against counterfeeding."""
    pre = (pattern, proxy)
    post = (proxy, replacement)
    return pre, post

